        "for pt in grid_points:\n",
        "    images = grid_points[pt]['images']\n",
        "\n",
        "    imagebox = OffsetImage(images.numpy().astype(\"uint8\"))\n",
        "    ab = AnnotationBbox(imagebox, pt, frameon = True)\n",
        "    ax.add_artist(ab)\n",
        "\n",
        "plt.show()"
